  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    # Build structures
    id_to_node = {}
    children_of = {}
    for n in nodes:
        nid = n['id']
        id_to_node[nid] = n
        children_of.setdefault(n['parent'], []).append(nid)
    root_id = None
    for n in nodes:
        if n['parent'] is None:
            root_id = n['id']
            break
    retained = set(id_to_node.keys())
    removed = []
    # Sort nodes: deeper first, then by id
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    for n in sorted_nodes:
        if not n['removable']:
            continue
        if n['id'] == root_id:
            continue
        if n['symbol'] in required_symbols:
            continue
        # Check if any child is still retained
        has_retained_child = False
        if n['id'] in children_of:
            for child_id in children_of[n['id']]:
                if child_id in retained:
                    has_retained_child = True
                    break
        if has_retained_child:
            continue
        # Can remove
        removed.append(n['id'])
        retained.discard(n['id'])
    retained_sorted = sorted(retained)
    return {'removed_node_ids': removed, 'retained_node_ids': retained_sorted}
